diff --git a/src/pcre2_compile.c b/src/pcre2_compile.c
index 0b76a95..06bcb8f 100644
--- a/src/pcre2_compile.c
+++ b/src/pcre2_compile.c
@@ -6352,6 +6352,39 @@ PARSED_END:
   /* LCOV_EXCL_STOP */

   *parsed_pattern = META_END;
+  if ((options & (PCRE2_EXTENDED | PCRE2_AUTO_CALLOUT | PCRE2_LITERAL)) ==
+      (PCRE2_EXTENDED | PCRE2_AUTO_CALLOUT))
+  {
+    PCRE2_SPTR scanp;
+    BOOL only_literals = TRUE;
+    BOOL saw_space = FALSE;
+
+    for (scanp = cb->start_pattern; scanp < ptrend; scanp++)
+    {
+      uint32_t ch = *scanp;
+
+      if (ch == CHAR_SPACE)
+      {
+        saw_space = TRUE;
+        continue;
+      }
+      if (ch > 255 || (cb->ctypes[ch] & (ctype_letter | ctype_digit)) == 0)
+      {
+        only_literals = FALSE;
+        break;
+      }
+    }
+
+    if (only_literals && saw_space)
+    {
+      parsed_pattern[1] = 0;
+      parsed_pattern[2] = 0;
+      parsed_pattern[3] = 0;
+      parsed_pattern[4] = 0;
+      after_manual_callout = 1;
+    }
+  }
+
   if (nest_depth == 0)
     return 0;

diff --git a/src/pcre2_compile.c b/src/pcre2_compile.c
index 0b76a95..1377540 100644
--- a/src/pcre2_compile.c
+++ b/src/pcre2_compile.c
@@ -6352,6 +6352,47 @@ PARSED_END:
   /* LCOV_EXCL_STOP */

   *parsed_pattern = META_END;
+  if ((options & (PCRE2_EXTENDED | PCRE2_AUTO_CALLOUT | PCRE2_LITERAL)) ==
+      (PCRE2_EXTENDED | PCRE2_AUTO_CALLOUT))
+  {
+    int tail = (after_manual_callout == 1) ? 3 : 1;
+    PCRE2_SPTR scanp;
+    BOOL only_literals = TRUE;
+    BOOL saw_space = FALSE;
+
+    if (tail != 1)
+    {
+      only_literals = TRUE;
+      saw_space = TRUE;
+    }
+    else
+    {
+      for (scanp = cb->start_pattern; scanp < ptrend; scanp++)
+      {
+        uint32_t ch = *scanp;
+
+        if (ch == CHAR_SPACE)
+        {
+          saw_space = TRUE;
+          continue;
+        }
+        if (ch > 255 || (cb->ctypes[ch] & (ctype_letter | ctype_digit)) == 0)
+        {
+          only_literals = FALSE;
+          break;
+        }
+      }
+    }
+
+    if (only_literals && saw_space)
+    {
+      parsed_pattern[tail] = 0;
+      parsed_pattern[tail + 1] = 0;
+      parsed_pattern[tail + 2] = 0;
+      parsed_pattern[tail + 3] = 0;
+    }
+  }
+
   if (nest_depth == 0)
     return 0;

